using Dsw2025Tpi.Data;
using Dsw2025Tpi.Domain.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Xunit;

namespace Dsw2025Tpi.Tests.Integration;

// Guards the test-only SQLite RowVersion simulation used by the fast integration host.
// SQL Server tests keep the real rowversion generated by the database.
[Trait("Category", "Integration")]
public class SqliteRowVersionSimulationTests
{
    private static byte[] RowVersionOf(Dsw2025TpiContext db, Product product) =>
        db.Entry(product).Property<byte[]>("RowVersion").CurrentValue;

    private static ApiFactory SeededFactory()
    {
        var factory = new ApiFactory();
        factory.CreateSeededClient(role: null).Dispose();
        return factory;
    }

    [Fact]
    public void Insert_NewProduct_ReceivesNonEmptyConcurrencyToken()
    {
        using var factory = SeededFactory();

        factory.Inspect(db =>
        {
            var product = db.Set<Product>().Single(p => p.Id == factory.ProductId);
            Assert.NotEmpty(RowVersionOf(db, product));
            Assert.True(db.Entry(product).Property("RowVersion").Metadata.IsConcurrencyToken);
        });
    }

    [Fact]
    public async Task Update_ModifiedProduct_ChangesRowVersion()
    {
        using var factory = SeededFactory();
        byte[] before = [];

        using (var scope = factory.Services.CreateScope())
        {
            var db = scope.ServiceProvider.GetRequiredService<Dsw2025TpiContext>();
            var product = await db.Set<Product>().SingleAsync(p => p.Id == factory.ProductId);
            before = RowVersionOf(db, product);
            product.StockQuantity -= 1;
            await db.SaveChangesAsync();
        }

        factory.Inspect(db =>
        {
            var product = db.Set<Product>().Single(p => p.Id == factory.ProductId);
            Assert.Equal(4, product.StockQuantity);
            Assert.NotEqual(before, RowVersionOf(db, product));
        });
    }

    [Fact]
    public async Task Update_TwoContextsReadSameVersion_SecondSaveThrowsConcurrencyConflict()
    {
        using var factory = SeededFactory();
        using var firstScope = factory.Services.CreateScope();
        using var secondScope = factory.Services.CreateScope();
        var first = firstScope.ServiceProvider.GetRequiredService<Dsw2025TpiContext>();
        var second = secondScope.ServiceProvider.GetRequiredService<Dsw2025TpiContext>();
        var firstProduct = await first.Set<Product>().SingleAsync(p => p.Id == factory.ProductId);
        var secondProduct = await second.Set<Product>().SingleAsync(p => p.Id == factory.ProductId);
        Assert.Equal(RowVersionOf(first, firstProduct), RowVersionOf(second, secondProduct));

        firstProduct.StockQuantity = 4;
        await first.SaveChangesAsync();
        secondProduct.StockQuantity = 3;

        await Assert.ThrowsAsync<DbUpdateConcurrencyException>(() => second.SaveChangesAsync());
        factory.Inspect(db => Assert.Equal(4, db.Set<Product>().Single(p => p.Id == factory.ProductId).StockQuantity));
    }
}
